function TaskRange:__init( lowestExpectedTaskID_, highestExpectedTaskID_ )
    self.lowestExpectedTaskID = lowestExpectedTaskID_
    self.highestExpectedTaskID = highestExpectedTaskID_
    self.lowestTaskIdx = -99
    self.highestTaskIdx = -99
    self.isInit = false
end


function TaskRange:__delete()
end



-- =========================================== Self ================================================ --


function TaskRange:IsSetedInInspector()
    return (self.lowestExpectedTaskID ~= "" and self.highestExpectedTaskID ~= "")
end


-- QuestCore
function TaskRange:Init( core_ )
    assert(core_.isInit == true, "quest_.isInit should be true")
    self.lowestTaskIdx = core_:GetTaskIdx(self.lowestExpectedTaskID)
    self.highestTaskIdx = core_:GetTaskIdx(self.highestExpectedTaskID)
    assert( self.lowestTaskIdx <= self.highestTaskIdx and self.lowestTaskIdx >= 0, "Invalid task range" )
    self.isInit = true
    --printInfo( self:ToString() )
end


function TaskRange:IsInRange(taskIdx_)
    assert( self.isInit == true, "TaskRange should be initialized first" )
    return taskIdx_ >= self.lowestTaskIdx and taskIdx_ <= self.highestTaskIdx
end


function TaskRange:ToString()
    return string.format("[TaskRange] Low: [%d]-%s; High: [%d]-%s", self.lowestTaskIdx, self.lowestExpectedTaskID, self.highestTaskIdx, self.highestExpectedTaskID)
end






return TaskRange

